import { DURATION_HISTOGRAM_BOUNDARIES_MS } from "../../config/defaults.js";
export function createStreamLifecycleInstruments(meter, config) {
    const prefix = config.prefix;
    const duration = (name, description) => meter.createHistogram(`${prefix}.stream.lifecycle.${name}`, {
        description,
        unit: "ms",
        advice: { explicitBucketBoundaries: [...DURATION_HISTOGRAM_BOUNDARIES_MS] },
    });
    return {
        streamLifecycleOutcomeCounter: meter.createCounter(`${prefix}.stream.lifecycle.outcomes`, {
            description: "Stream lifecycle terminal outcomes",
            unit: "outcomes",
        }),
        streamLifecycleDeadlineCounter: meter.createCounter(`${prefix}.stream.lifecycle.deadlines`, {
            description: "Stream lifecycle deadlines that fired",
            unit: "deadlines",
        }),
        streamLifecycleTelemetryCounter: meter.createCounter(`${prefix}.stream.lifecycle.telemetry`, {
            description: "Stream lifecycle telemetry frames",
            unit: "frames",
        }),
        streamLifecycleRepairCounter: meter.createCounter(`${prefix}.stream.lifecycle.repairs`, {
            description: "Stream lifecycle protocol repairs",
            unit: "repairs",
        }),
        streamLifecycleShadowDivergenceCounter: meter.createCounter(`${prefix}.stream.lifecycle.shadow.divergences`, {
            description: "Stream lifecycle shadow divergences by category",
            unit: "divergences",
        }),
        streamLifecycleAttemptDuration: duration("attempt.duration", "Provider stream attempt duration"),
        streamLifecycleFirstProgressDuration: duration("first_progress.duration", "Time to first semantic progress"),
        streamLifecycleSemanticIdleDuration: duration("semantic_idle.duration", "Semantic idle duration between progress"),
        streamLifecycleToolInputDuration: duration("tool_input.duration", "Tool input assembly duration"),
        streamLifecycleToolExecutionDuration: duration("tool_execution.duration", "Provider-visible tool execution duration"),
    };
}
